CREATE DATABASE IF NOT EXISTS electronics_ecommerce CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE electronics_ecommerce;
CREATE TABLE `User` (userId int(11) NOT NULL AUTO_INCREMENT, fullName varchar(255) NOT NULL, phoneNumber varchar(255) NOT NULL, PRIMARY KEY (userId));
CREATE TABLE Customer (userId int(11) NOT NULL, registeredAt datetime NOT NULL, dateOfBirth date, PRIMARY KEY (userId));
CREATE TABLE Employee (userId int(11) NOT NULL, employeeCode varchar(255) NOT NULL UNIQUE, role varchar(255) NOT NULL, PRIMARY KEY (userId));
CREATE TABLE Account (accountId int(11) NOT NULL AUTO_INCREMENT, userId int(11) NOT NULL UNIQUE, email varchar(254) NOT NULL UNIQUE, passwordHash varchar(512) NOT NULL, isActive tinyint(1) NOT NULL, PRIMARY KEY (accountId));
CREATE TABLE AuthSession (tokenHash char(64) NOT NULL, accountId int(11) NOT NULL, createdAt datetime NOT NULL, expiresAt datetime NOT NULL, PRIMARY KEY (tokenHash));
CREATE TABLE AuditLog (auditLogId int(11) NOT NULL AUTO_INCREMENT, employeeId int(11) NOT NULL, occurredAt datetime NOT NULL, action varchar(255) NOT NULL, target varchar(255) NOT NULL, beforeValue text NOT NULL, afterValue text NOT NULL, PRIMARY KEY (auditLogId));
CREATE TABLE Cart (cartId int(11) NOT NULL AUTO_INCREMENT, customerId int(11) NOT NULL UNIQUE, createdAt datetime NOT NULL, PRIMARY KEY (cartId));
CREATE TABLE CartItem (cartItemId int(11) NOT NULL AUTO_INCREMENT, cartId int(11) NOT NULL, articleId int(11) NOT NULL, quantity int(11) NOT NULL, PRIMARY KEY (cartItemId));
CREATE TABLE `Order` (orderId int(11) NOT NULL AUTO_INCREMENT, customerId int(11) NOT NULL, orderNumber varchar(255) NOT NULL UNIQUE, placedAt datetime NOT NULL, status varchar(255) NOT NULL, totalAmount decimal(18, 2) NOT NULL, shippingFee decimal(18, 2) NOT NULL, shippingAddress varchar(500) NOT NULL, shippingMethod varchar(255) NOT NULL, paymentMethod varchar(255) NOT NULL, holdExpiresAt datetime NULL, packedAt datetime NULL, PRIMARY KEY (orderId));
CREATE TABLE OrderItem (orderItemId int(11) NOT NULL AUTO_INCREMENT, orderId int(11) NOT NULL, articleId int(11) NOT NULL, quantity int(11) NOT NULL, unitPrice decimal(18, 2) NOT NULL, productNameSnapshot varchar(255) NOT NULL, specificationSnapshot text NOT NULL, warrantySnapshot text NOT NULL, PRIMARY KEY (orderItemId));
CREATE TABLE Payment (paymentId int(11) NOT NULL AUTO_INCREMENT, orderId int(11) NOT NULL UNIQUE, amount decimal(18, 2) NOT NULL, status varchar(255) NOT NULL, transactionCode varchar(255) NOT NULL, PRIMARY KEY (paymentId));
CREATE TABLE PaymentEvent (paymentEventId int(11) NOT NULL AUTO_INCREMENT, paymentId int(11) NOT NULL, employeeId int(11), result varchar(255) NOT NULL, referenceCode varchar(255) NOT NULL, eventKey varchar(255) NOT NULL, recordedAt datetime NOT NULL, PRIMARY KEY (paymentEventId));
CREATE TABLE Invoice (invoiceId int(11) NOT NULL AUTO_INCREMENT, orderId int(11) NOT NULL UNIQUE, invoiceNumber varchar(255) NOT NULL UNIQUE, issuedAt datetime NOT NULL, totalAmount decimal(18, 2) NOT NULL, PRIMARY KEY (invoiceId));
CREATE TABLE Shipment (shipmentId int(11) NOT NULL AUTO_INCREMENT, orderId int(11) NOT NULL UNIQUE, trackingNumber varchar(255) NOT NULL UNIQUE, status varchar(255) NOT NULL, deliveredAt datetime NULL, PRIMARY KEY (shipmentId));
CREATE TABLE Category (categoryId int(11) NOT NULL AUTO_INCREMENT, groupName varchar(255) NOT NULL, subCategory varchar(255) NOT NULL, PRIMARY KEY (categoryId));
CREATE TABLE Product (articleId int(11) NOT NULL AUTO_INCREMENT, categoryId int(11) NOT NULL, productName varchar(255) NOT NULL, brand varchar(255) NOT NULL, price decimal(18, 2) NOT NULL, isActive tinyint(1) NOT NULL, technicalSpecs text NOT NULL, warrantyTerms text NOT NULL, imagePath varchar(2048) NOT NULL, imageEmbedding text NOT NULL comment 'Serialized JSON array of embedding coordinates.', textEmbedding text NOT NULL comment 'Serialized JSON array of embedding coordinates.', PRIMARY KEY (articleId));
CREATE TABLE MobilePhone (articleId int(11) NOT NULL, operatingSystem varchar(255) NOT NULL, simType varchar(255) NOT NULL, PRIMARY KEY (articleId));
CREATE TABLE Laptop (articleId int(11) NOT NULL, processor varchar(255) NOT NULL, memory varchar(255) NOT NULL, PRIMARY KEY (articleId));
CREATE TABLE Tablet (articleId int(11) NOT NULL, screenSize varchar(255) NOT NULL, stylusSupport tinyint(1) NOT NULL, PRIMARY KEY (articleId));
CREATE TABLE SmartWatch (articleId int(11) NOT NULL, waterResistance varchar(255) NOT NULL, PRIMARY KEY (articleId));
CREATE TABLE Headphones (articleId int(11) NOT NULL, connectionType varchar(255) NOT NULL, PRIMARY KEY (articleId));
CREATE TABLE Inventory (articleId int(11) NOT NULL, onHandQuantity int(11) NOT NULL, PRIMARY KEY (articleId));
CREATE TABLE StockCommitment (commitmentId int(11) NOT NULL AUTO_INCREMENT, orderId int(11) NOT NULL, inventoryArticleId int(11) NOT NULL, quantity int(11) NOT NULL, status varchar(255) NOT NULL, expiresAt datetime NULL, PRIMARY KEY (commitmentId));
CREATE TABLE StockMovement (movementId int(11) NOT NULL AUTO_INCREMENT, inventoryArticleId int(11) NOT NULL, receiptId int(11), quantity int(11) NOT NULL, type varchar(255) NOT NULL, reason varchar(255) NOT NULL, occurredAt datetime NOT NULL, PRIMARY KEY (movementId));
CREATE TABLE StockReceipt (receiptId int(11) NOT NULL AUTO_INCREMENT, receiptNumber varchar(255) NOT NULL UNIQUE, receivedAt datetime NOT NULL, PRIMARY KEY (receiptId));
CREATE TABLE SearchQuery (queryId int(11) NOT NULL AUTO_INCREMENT, customerId int(11), createdAt datetime NOT NULL, searchCriteria text NOT NULL, PRIMARY KEY (queryId));
CREATE TABLE TextQuery (queryId int(11) NOT NULL, queryText text NOT NULL, PRIMARY KEY (queryId));
CREATE TABLE VoiceQuery (queryId int(11) NOT NULL, audioReference varchar(255) NOT NULL, transcribedText text NOT NULL, PRIMARY KEY (queryId));
CREATE TABLE ImageQuery (queryId int(11) NOT NULL, imageReference varchar(255) NOT NULL, selectedRegion varchar(255) NOT NULL, PRIMARY KEY (queryId));
CREATE TABLE SearchResult (queryId int(11) NOT NULL, articleId int(11) NOT NULL, rank int(11) NOT NULL, score double NOT NULL, PRIMARY KEY (queryId, articleId));
CREATE UNIQUE INDEX uq_Employee_employeeCode ON Employee (employeeCode);
CREATE UNIQUE INDEX uq_Account_userId ON Account (userId);
CREATE UNIQUE INDEX uq_Account_email ON Account (email);
CREATE UNIQUE INDEX uq_Cart_customerId ON Cart (customerId);
CREATE UNIQUE INDEX uq_CartItem_cartId_articleId ON CartItem (cartId, articleId);
CREATE UNIQUE INDEX uq_Order_orderNumber ON `Order` (orderNumber);
CREATE UNIQUE INDEX uq_Payment_orderId ON Payment (orderId);
CREATE UNIQUE INDEX uq_PaymentEvent_paymentId_eventKey ON PaymentEvent (paymentId, eventKey);
CREATE UNIQUE INDEX uq_Invoice_orderId ON Invoice (orderId);
CREATE UNIQUE INDEX uq_Invoice_invoiceNumber ON Invoice (invoiceNumber);
CREATE UNIQUE INDEX uq_Shipment_orderId ON Shipment (orderId);
CREATE UNIQUE INDEX uq_Shipment_trackingNumber ON Shipment (trackingNumber);
CREATE UNIQUE INDEX uq_StockReceipt_receiptNumber ON StockReceipt (receiptNumber);
CREATE UNIQUE INDEX uq_SearchResult_queryId_rank ON SearchResult (queryId, rank);
ALTER TABLE Customer ADD CONSTRAINT fk_Customer_userId FOREIGN KEY (userId) REFERENCES `User` (userId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Employee ADD CONSTRAINT fk_Employee_userId FOREIGN KEY (userId) REFERENCES `User` (userId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE MobilePhone ADD CONSTRAINT fk_MobilePhone_articleId FOREIGN KEY (articleId) REFERENCES Product (articleId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Laptop ADD CONSTRAINT fk_Laptop_articleId FOREIGN KEY (articleId) REFERENCES Product (articleId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Tablet ADD CONSTRAINT fk_Tablet_articleId FOREIGN KEY (articleId) REFERENCES Product (articleId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE SmartWatch ADD CONSTRAINT fk_SmartWatch_articleId FOREIGN KEY (articleId) REFERENCES Product (articleId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Headphones ADD CONSTRAINT fk_Headphones_articleId FOREIGN KEY (articleId) REFERENCES Product (articleId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE TextQuery ADD CONSTRAINT fk_TextQuery_queryId FOREIGN KEY (queryId) REFERENCES SearchQuery (queryId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE VoiceQuery ADD CONSTRAINT fk_VoiceQuery_queryId FOREIGN KEY (queryId) REFERENCES SearchQuery (queryId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE ImageQuery ADD CONSTRAINT fk_ImageQuery_queryId FOREIGN KEY (queryId) REFERENCES SearchQuery (queryId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Account ADD CONSTRAINT fk_Account_userId FOREIGN KEY (userId) REFERENCES `User` (userId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE AuthSession ADD CONSTRAINT fk_AuthSession_accountId FOREIGN KEY (accountId) REFERENCES Account (accountId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE AuditLog ADD CONSTRAINT fk_AuditLog_employeeId FOREIGN KEY (employeeId) REFERENCES Employee (userId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Cart ADD CONSTRAINT fk_Cart_customerId FOREIGN KEY (customerId) REFERENCES Customer (userId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE `Order` ADD CONSTRAINT fk_Order_customerId FOREIGN KEY (customerId) REFERENCES Customer (userId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE SearchQuery ADD CONSTRAINT fk_SearchQuery_customerId FOREIGN KEY (customerId) REFERENCES Customer (userId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE CartItem ADD CONSTRAINT fk_CartItem_cartId FOREIGN KEY (cartId) REFERENCES Cart (cartId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE CartItem ADD CONSTRAINT fk_CartItem_articleId FOREIGN KEY (articleId) REFERENCES Product (articleId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE OrderItem ADD CONSTRAINT fk_OrderItem_orderId FOREIGN KEY (orderId) REFERENCES `Order` (orderId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE OrderItem ADD CONSTRAINT fk_OrderItem_articleId FOREIGN KEY (articleId) REFERENCES Product (articleId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Payment ADD CONSTRAINT fk_Payment_orderId FOREIGN KEY (orderId) REFERENCES `Order` (orderId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE PaymentEvent ADD CONSTRAINT fk_PaymentEvent_paymentId FOREIGN KEY (paymentId) REFERENCES Payment (paymentId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE PaymentEvent ADD CONSTRAINT fk_PaymentEvent_employeeId FOREIGN KEY (employeeId) REFERENCES Employee (userId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Shipment ADD CONSTRAINT fk_Shipment_orderId FOREIGN KEY (orderId) REFERENCES `Order` (orderId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Invoice ADD CONSTRAINT fk_Invoice_orderId FOREIGN KEY (orderId) REFERENCES `Order` (orderId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Product ADD CONSTRAINT fk_Product_categoryId FOREIGN KEY (categoryId) REFERENCES Category (categoryId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE Inventory ADD CONSTRAINT fk_Inventory_articleId FOREIGN KEY (articleId) REFERENCES Product (articleId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE StockMovement ADD CONSTRAINT fk_StockMovement_inventoryArticleId FOREIGN KEY (inventoryArticleId) REFERENCES Inventory (articleId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE StockCommitment ADD CONSTRAINT fk_StockCommitment_inventoryArticleId FOREIGN KEY (inventoryArticleId) REFERENCES Inventory (articleId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE StockCommitment ADD CONSTRAINT fk_StockCommitment_orderId FOREIGN KEY (orderId) REFERENCES `Order` (orderId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE StockMovement ADD CONSTRAINT fk_StockMovement_receiptId FOREIGN KEY (receiptId) REFERENCES StockReceipt (receiptId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE SearchResult ADD CONSTRAINT fk_SearchResult_queryId FOREIGN KEY (queryId) REFERENCES SearchQuery (queryId) ON UPDATE Restrict ON DELETE Restrict;
ALTER TABLE SearchResult ADD CONSTRAINT fk_SearchResult_articleId FOREIGN KEY (articleId) REFERENCES Product (articleId) ON UPDATE Restrict ON DELETE Restrict;
